{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "The outcome measurements of this review were reported in terms of the percentages of participants with a good level of knowledge, favorable attitudes, and good practices toward AMR. Furthermore, associated factors were narrated in texts, as we identified insufficient data on factors influencing the outcome to pool the odds ratio (OR)",
      "reason": "The effect measure for each outcome is specified: pooled percentages (prevalence) for knowledge, attitudes, and practices, with associated factors narrated rather than pooled as odds ratios. The abstract and results confirm pooled prevalence with 95% CIs."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": "text_11",
      "quote": "0%,25 to 50%,50 to 75%, and greater than or equal to75% indicated no heterogeneity, low heterogeneity, moderate heterogeneity, and high heterogeneity respectively",
      "reason": "Thresholds are reported only for interpreting heterogeneity (I2), not for interpreting the magnitude of effect sizes; no thresholds or rationale for interpreting the effect size itself are provided."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No methods for re-expressing synthesized results using another effect measure are described anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": "text_11",
